package com.hardcraft.collections;
import static org.junit.jupiter.api.Assertions.*;import java.nio.file.Path;import java.util.UUID;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;
class CollectionRepositoryTest{@Test void discoveriesAndMilestonesAreIdempotent(@TempDir Path dir){Path db=dir.resolve("db");UUID owner=UUID.randomUUID();CollectionRepository first=new CollectionRepository(db);first.migrate();assertTrue(first.discover(owner,"MOB","minecraft:zombie"));assertFalse(first.discover(owner,"MOB","minecraft:zombie"));assertEquals(1,first.count(owner));assertTrue(first.claim(owner,1));CollectionRepository restarted=new CollectionRepository(db);assertEquals(1,restarted.count(owner));assertFalse(restarted.claim(owner,1));assertThrows(IllegalArgumentException.class,()->restarted.discover(owner,"MOB","forged display name"));}}